package com.graalmail.provider.proton;

import java.time.Duration;
import javax.net.ssl.SSLContext;

/**
 * Immutable configuration for a local Proton Mail Bridge connection.
 *
 * <p>The bridge password is a secret generated by Proton Mail Bridge; it is never
 * included in {@link #toString()} and must never be logged.</p>
 */
public final class ProtonBridgeConfig {

    /** Default host of a local Proton Mail Bridge instance. */
    public static final String DEFAULT_HOST = "127.0.0.1";
    /** Default IMAP port exposed by Proton Mail Bridge. */
    public static final int DEFAULT_IMAP_PORT = 1143;
    /** Default SMTP port exposed by Proton Mail Bridge. */
    public static final int DEFAULT_SMTP_PORT = 1025;

    private final String bridgeHost;
    private final int imapPort;
    private final int smtpPort;
    private final String bridgeUsername;
    private final String bridgePassword;
    private final SSLContext sslContext;
    private final String pinnedCertificateFingerprint;
    private final Duration connectTimeout;
    private final Duration readTimeout;
    private final TlsMode tlsMode;

    private ProtonBridgeConfig(Builder b) {
        this.bridgeHost = b.bridgeHost;
        this.imapPort = b.imapPort;
        this.smtpPort = b.smtpPort;
        this.bridgeUsername = b.bridgeUsername;
        this.bridgePassword = b.bridgePassword;
        this.sslContext = b.sslContext;
        this.pinnedCertificateFingerprint = b.pinnedCertificateFingerprint;
        this.connectTimeout = b.connectTimeout;
        this.readTimeout = b.readTimeout;
        this.tlsMode = b.tlsMode;
    }

    public static Builder builder() {
        return new Builder();
    }

    public String bridgeHost() { return bridgeHost; }
    public int imapPort() { return imapPort; }
    public int smtpPort() { return smtpPort; }
    public String bridgeUsername() { return bridgeUsername; }
    public String bridgePassword() { return bridgePassword; }
    public SSLContext sslContext() { return sslContext; }
    public String pinnedCertificateFingerprint() { return pinnedCertificateFingerprint; }
    public Duration connectTimeout() { return connectTimeout; }
    public Duration readTimeout() { return readTimeout; }
    public TlsMode tlsMode() { return tlsMode; }

    public boolean hasPinnedCertificate() {
        return pinnedCertificateFingerprint != null && !pinnedCertificateFingerprint.isBlank();
    }

    /** Builder for {@link ProtonBridgeConfig}. */
    public static final class Builder {
        private String bridgeHost = DEFAULT_HOST;
        private int imapPort = DEFAULT_IMAP_PORT;
        private int smtpPort = DEFAULT_SMTP_PORT;
        private String bridgeUsername = "";
        private String bridgePassword = "";
        private SSLContext sslContext;
        private String pinnedCertificateFingerprint = "";
        private Duration connectTimeout = Duration.ofSeconds(10);
        private Duration readTimeout = Duration.ofSeconds(60);
        private TlsMode tlsMode = TlsMode.STARTTLS;

        public Builder bridgeHost(String v) { this.bridgeHost = v; return this; }
        public Builder imapPort(int v) { this.imapPort = v; return this; }
        public Builder smtpPort(int v) { this.smtpPort = v; return this; }
        public Builder bridgeUsername(String v) { this.bridgeUsername = v; return this; }
        public Builder bridgePassword(String v) { this.bridgePassword = v; return this; }
        public Builder sslContext(SSLContext v) { this.sslContext = v; return this; }
        public Builder pinnedCertificateFingerprint(String v) { this.pinnedCertificateFingerprint = v; return this; }
        public Builder connectTimeout(Duration v) { this.connectTimeout = v; return this; }
        public Builder readTimeout(Duration v) { this.readTimeout = v; return this; }
        public Builder tlsMode(TlsMode v) { this.tlsMode = v; return this; }

        public ProtonBridgeConfig build() {
            if (bridgeHost == null || bridgeHost.isBlank()) {
                throw new IllegalArgumentException("bridgeHost must not be blank");
            }
            if (imapPort <= 0 || imapPort > 65535 || smtpPort <= 0 || smtpPort > 65535) {
                throw new IllegalArgumentException("Ports must be within 1..65535");
            }
            if (connectTimeout == null || readTimeout == null) {
                throw new IllegalArgumentException("Timeouts must not be null");
            }
            return new ProtonBridgeConfig(this);
        }
    }

    /** How the bridge listener negotiates TLS. */
    public enum TlsMode {
        /** Plain greeting followed by a STARTTLS upgrade; the current Bridge default. */
        STARTTLS,
        /** Implicit TLS from the first byte. */
        SSL
    }

    @Override
    public String toString() {
        return "ProtonBridgeConfig{host=" + bridgeHost
                + ", imapPort=" + imapPort
                + ", smtpPort=" + smtpPort
                + ", username=" + bridgeUsername
                + ", password=[redacted]"
                + ", pinnedCertificate=" + (hasPinnedCertificate() ? "yes" : "no")
                + ", tlsMode=" + tlsMode
                + '}';
    }
}
